from pathlib import Path
root=Path(__file__).parent
checks=[]
def check(name,ok): checks.append((name,bool(ok)))
client=(root/'mobile/src/api/client.ts').read_text()
app=(root/'mobile/App.tsx').read_text()
doc=(root/'mobile/src/screens/DoctorProfileScreen.tsx').read_text()
review=(root/'mobile/src/screens/OwnerReviewScreen.tsx').read_text()
services=(root/'mobile/src/screens/FacilityServicesScreen.tsx').read_text()
dash=(root/'mobile/src/screens/ProviderDashboardScreen.tsx').read_text()
fac=(root/'src/facilities/facilities.controller.ts').read_text()
fac_service=(root/'src/facilities/facilities.service.ts').read_text()
fac_dto=(root/'src/facilities/dto/update-facility-service.dto.ts').read_text()
doctor=(root/'src/doctors/doctors.controller.ts').read_text()
check('doctor profile editor screen exists',(root/'mobile/src/screens/DoctorProfileScreen.tsx').exists())
check('doctor profile form includes required profile fields',all(x in doc for x in ['fullName','specialty','clinicName','address','city']))
check('optional doctor fields remain optional in mobile editor',all(x in doc for x in ['subSpecialty','qualifications','experience','bio','photoUrl']))
check('doctor profile save API client wired','saveDoctorProfile:' in client and "'/doctors/me/profile'" in client)
check('doctor profile submit API client wired','submitDoctorProfile:' in client and "'/doctors/me/profile/submit'" in client)
check('doctor profile submit route remains doctor-only',"@Post('me/profile/submit')" in doctor and '@Roles(UserRole.DOCTOR)' in doctor)
check('doctor dashboard links to profile editor','onManageProfile' in dash and 'إدارة الملف المهني' in dash)
check('profile screen navigation is wired','DoctorProfileScreen' in app and "name=\"DoctorProfile\"" in app)
check('owner pending doctor review API wired','pendingDoctors:' in client and "'/doctors/owner/pending'" in client)
check('owner doctor decision API wired','reviewDoctor:' in client and '/doctors/owner/${id}/review' in client)
check('owner pending facility review route is protected',"@Get('owner/pending')" in fac and "@Roles(UserRole.OWNER)" in fac)
check('owner pending facility review API wired','pendingFacilities:' in client and "'/facilities/owner/pending'" in client)
check('owner can approve or reject doctor profiles in UI',all(x in review for x in ['approved','rejected','موافقة','رفض']))
check('owner can approve or reject facilities in UI','reviewFacility' in review and 'facilities.map' in review)
check('review screen navigation and owner dashboard button wired','OwnerReviewScreen' in app and 'onReview' in dash)
check('facility service update DTO validates optional fields',all(x in fac_dto for x in ['priceIqd','expectedDurationMinutes','isActive','IsBoolean']))
check('owner facility service update route protected',"@Patch('owner/:id/services/:serviceId')" in fac and '@Roles(UserRole.OWNER)' in fac)
check('service update is scoped to authenticated owner','ownedFacility(ownerId,facilityId)' in fac_service and 'updateService(ownerId:string' in fac_service)
check('service deactivation checks future active bookings','b.startsAt > :now' in fac_service and 'FacilityBookingStatus.REQUESTED' in fac_service and 'FacilityBookingStatus.CONFIRMED' in fac_service)
check('owner service listing includes inactive services','ownerServices(ownerId:string' in fac_service and "where:{facilityId:facility.id}" in fac_service)
check('service management screen supports create price and duration','addFacilityService' in services and 'priceIqd' in services and 'expectedDurationMinutes' in services)
check('service management screen supports pause and reactivation','isActive' in services and 'إيقاف الخدمة' in services and 'تفعيل الخدمة' in services)
check('service management API client methods wired','addFacilityService:' in client and 'updateFacilityService:' in client)
check('owner dashboard links to service manager','onManageServices' in dash and 'إدارة الخدمات والأسعار' in dash and 'FacilityServicesScreen' in app)
check('schedule editor excludes inactive services','filter((x:any)=>x.isActive!==false)' in (root/'mobile/src/screens/ScheduleManagementScreen.tsx').read_text())
check('phase documentation records upload limitation and no migration','Direct secure file upload' in (root/'docs/phase-v34-provider-profiles-services-and-owner-review.md').read_text() and 'No database migration' in (root/'docs/phase-v34-provider-profiles-services-and-owner-review.md').read_text())
for name,ok in checks: print(('PASS' if ok else 'FAIL')+' '+name)
print(f'V34: {sum(ok for _,ok in checks)}/{len(checks)}')
raise SystemExit(0 if all(ok for _,ok in checks) else 1)
